def load():
    out = {}
    for line in RAW.strip().splitlines():
        code, names = line.split('|', 1)
        for item in names.split(';'):
            item = item.strip()
            if not item: continue
            n, _, d = item.partition('=')
            out[n.strip()] = (code, d.strip())
    return out
